// Precompiles the JSON Schemas into standalone ESM validators.
//
// The renderer runs inside a Tauri window whose CSP deliberately forbids
// `unsafe-eval`; Ajv's normal runtime code generation would be blocked.
// Standalone validators are plain generated JavaScript, so the same schema
// is enforced at runtime and at build time without weakening the CSP.
//
// Usage:
//   node scripts/build-validators.mjs          # write generated files
//   node scripts/build-validators.mjs --check  # fail on drift

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import Ajv2020 from "ajv/dist/2020.js";
import standalone from "ajv/dist/standalone/index.js";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
// In the template source this script lives in starter/scripts and the
// schemas are one level up; in a generated project both are at the root.
const projectRoot = path.resolve(scriptDir, "..");
const templateRoot = path.resolve(scriptDir, "../..");
const inTemplate = fs.existsSync(path.join(templateRoot, "schema/page.schema.json"));
const root = inTemplate ? templateRoot : projectRoot;
const outputDir = path.join(projectRoot, "src/validation/generated");
const checkOnly = process.argv.includes("--check");

// Ajv's standalone emitter still emits a CommonJS `require` for the
// ucs2length helper even in ESM mode. Inline the (tiny, deterministic)
// helper so the module runs in the browser bundle without `require`.
const UCS2_LENGTH = `const func1 = (str) => {
  const length = str.length;
  let count = 0;
  let index = 0;
  while (index < length) {
    count += 1;
    const code = str.charCodeAt(index++);
    if (code >= 0xd800 && code <= 0xdbff && index < length) {
      const next = str.charCodeAt(index);
      if ((next & 0xfc00) === 0xdc00) index += 1;
    }
  }
  return count;
};`;

const schemas = [
  ["page", "page.schema.json", "page-validator.mjs"],
  ["project", "project.schema.json", "project-validator.mjs"],
];

let drift = false;

for (const [name, schemaFile, outputFile] of schemas) {
  const schema = JSON.parse(
    fs.readFileSync(path.join(root, "schema", schemaFile), "utf8"),
  );
  const ajv = new Ajv2020({
    allErrors: true,
    strict: false,
    allowUnionTypes: true,
    code: { source: true, esm: true, lines: true },
  });
  const validate = ajv.compile(schema);
  const generated = standalone(ajv, validate).replace(
    'const func1 = require("ajv/dist/runtime/ucs2length").default;',
    UCS2_LENGTH,
  );
  const source = [
    "// Generated by templates/s3/scripts/build-validators.mjs from",
    `// schema/${schemaFile}. Do not edit by hand; rerun the generator.`,
    generated,
    "",
  ].join("\n");
  const destination = path.join(outputDir, outputFile);
  if (checkOnly) {
    const existing = fs.existsSync(destination)
      ? fs.readFileSync(destination, "utf8")
      : "";
    if (existing !== source) {
      console.error(`生成的 ${name} 校验器与 schema 不一致：${destination}`);
      drift = true;
    }
  } else {
    fs.mkdirSync(outputDir, { recursive: true });
    fs.writeFileSync(destination, source, "utf8");
    console.log(`wrote ${path.relative(root, destination)} (${source.length} bytes)`);
  }
}

if (checkOnly) {
  if (drift) {
    console.error("请运行 node scripts/build-validators.mjs 重新生成校验器。");
    process.exit(1);
  }
  console.log("生成的页面/项目校验器与 schema 一致。");
}
